-- Gaia Family server: the server changelog read by the newspaper (2026-10-26).
--
-- Ours, not upstream. One plain sentence per change players can notice,
-- newest last, in the words a player would use (no file names). The Gaia
-- Times prints the changes of the last FamilyChangelogDays days in its
-- "Server updates" section. Every change committed to the family branch adds
-- its line here (see FAMILY.md, "Newspaper").

FamilyChangelogDays = 7

FamilyChangelog = {
	{ "2026-10-17", "Map discovery: Start Discovering in the Cyclopedia map and find the pink vortexes (Measuring Tibia)." },
	{ "2026-10-17", "Offline training counts the whole time away, up to a year; a bed in your house restores health, mana and soul at login." },
	{ "2026-10-17", "Sword, axe and club fighting always share the highest of the three." },
	{ "2026-10-17", "Shared party experience has no level limit and no distance or activity rule." },
	{ "2026-10-17", "Bosses have no cooldown." },
	{ "2026-10-17", "Fresh corpses can be moved right away." },
	{ "2026-10-17", "The Way of the Monk is playable and every monk item can be found." },
	{ "2026-10-18", "The spell list shows only the spells you have learned." },
	{ "2026-10-18", "Vocation bonuses: extra regeneration and critical chance while fed." },
	{ "2026-10-18", "The Tibiadrome arena is open behind the demon trophies." },
	{ "2026-10-18", "NPCs understand whole words first (no more answers to words hidden inside others)." },
	{ "2026-10-18", "Bosses drop Tibia Coins." },
	{ "2026-10-18", "Creatures drop the loot TibiaWiki lists for them." },
	{ "2026-10-18", "The market always has offers to buy and sell." },
	{ "2026-10-18", "The First Dragon: every dragon chest and sacred site counts." },
	{ "2026-10-19", "Houses for sale are furnished; the furniture goes away when you buy one." },
	{ "2026-10-19", "Prey and Hunting Task rerolls and list choices are free." },
	{ "2026-10-19", "Mounts run faster on their home terrain (say !mounts)." },
	{ "2026-10-19", "Edron City Tasks: Daniel Steelsoul has 13 tasks, several at once, at any level." },
	{ "2026-10-20", "New quests: Sinatuki's fish, the Festive Outfit addons, Waterskin of Mead, The Spirit Will Get You and Pilgrimage of Ashes." },
	{ "2026-10-20", "The quest tracker updates right away." },
	{ "2026-10-20", "Skill bars and the spell list stay right after dying." },
	{ "2026-10-20", "The adventurer's stone works anywhere outside a fight; the battle icon ends when no enemy is near." },
	{ "2026-10-21", "Werebadgers and werefoxes on the Troll Sabotage path come out only at night." },
	{ "2026-10-21", "Map discovery points are never inside houses." },
	{ "2026-10-21", "Troll Sabotage: Chief Grarkharok accepts the lady's name." },
	{ "2026-10-21", "Daily reward days 3 and 5 give an XP boost and 25 Tibia Coins instead of Prey rerolls." },
	{ "2026-10-21", "Venore Daily Tasks (ask Norman) and the Braindeath near Beregar's coffin." },
	{ "2026-10-21", "Walter Jaeger sells the Falconer outfit, its addons and the Antelope for Hunting Task points." },
	{ "2026-10-21", "Hunting Tasks pay 10 times the points and a new task can be chosen at once." },
	{ "2026-10-22", "Great mana potions can be drunk by every vocation from level 80." },
	{ "2026-10-22", "Training weapons from the daily reward can be thrown away." },
	{ "2026-10-23", "Tibiadrome: Lorenzo trades Drome points for rewards; rotations every two weeks; 10 minutes between runs." },
	{ "2026-10-23", "Rotworms no longer drop legion helmets." },
	{ "2026-10-23", "Magic level trains faster on statues and dummies, and statue training is twice as fast." },
	{ "2026-10-25", "Tibiadrome runs go on when you take the stairs to the arena's lower floors." },
	{ "2026-10-25", "The Citizen addons show in the quest log." },
	{ "2026-10-25", "New quest: Top of the City in Yalahar (ask Iriana)." },
	{ "2026-10-25", "Exaltation Forge: more dust, cheaper tiers and a better success rate; more influenced creatures near players." },
	{ "2026-10-25", "The market also sells quest items." },
	{ "2026-10-26", "The Gaia Times prints server updates and the adventurers' chronicle of the last day played." },
	{ "2026-10-26", "The Inquisition bosses, the Ankrahmun pharaohs and The Lord of the Lice drop Tibia Coins too." },
	{ "2026-10-26", "New quest: Cartography 101 (ask Rotem Valos in the Adventurers' Guild about a map)." },
	{ "2026-10-26", "New quest: Dragon Slayer Outfits (ask Big Ben in Ab'Dendriel about the dragon slayer attire); Albino Dragons live in five dragon lairs; the First Dragon quest is open all year." },
	{ "2026-10-26", "The adventurers' chronicle records Goshnar's Megalomania bosstiary levels too." },
	{ "2026-10-27", "New promotions at levels 200, 400, 600, 800 and 1000 (say 'promotion' to King Tibianus and the other promoting NPCs; !promotion shows your bonuses)." },
	{ "2026-10-27", "Raid bosses really come now: Orshabaal, Morgaroth, Ghazbaran and Ferumbras about every 20 hours of play, rarer bosses and the Ruthless Seven about every 8, common ones about every 3; other invasions come in random order." },
	{ "2026-10-27", "22 rare bosses that never appeared now come too, on the same timers: among them Hairman the Huge, The Evil Eye, the Rotworm Queen, Willi Wasp, Xenia, Zarabustor, Morshabaal and The Abomination." },
	{ "2026-10-27", "Morshabaal and The Abomination are made for two players: far less health, softer hits (none above 1,500) and much weaker healing." },
	{ "2026-10-27", "Small bosses (20,000 health or less, like Hairman the Huge or the pharaohs) keep their full health; Feroxa's phases and Zamulosh's clones work again." },
	{ "2026-10-28", "Bosses have their Tibia cooldown again (20 hours for most), but every boss cooldown also ends at midnight: a boss killed at 23:00 can be fought again at 00:00." },
	{ "2026-10-28", "The Lion Sanctum doors open for level 250 or more, so its four bosses can be fought (until the An Ancient Feud mission exists)." },
	{ "2026-10-28", "New quest: Grimvale Quest, The Curse Spreads (ask Daniel Steelsoul in Edron about the curse). The five were-beast leaders can only be fought during its last step or after it." },
	{ "2026-10-28", "New quest: Grimvale Quest, An Ancient Feud (after The Curse Spreads, ask Daniel Steelsoul about the lions). The Lion Sanctum doors now open through this mission instead of at level 250." },
	{ "2026-10-28", "The server now notes when the main backpack window or the Manage Containers choices get lost, to find out why they sometimes reset at login (nothing changes in the game)." },
	{ "2026-10-28", "The Curse Spreads: Milos' parchments are in any bookcase of the central tower library (floor +4 one, floor +3 two); the bookcases now always answer, and Milos and the quest log say where to look." },
	{ "2026-10-28", "New quest: Grimvale Quest, The Curse of the Full Moon (Maeryn is on Grimvale now): nightshade blossoms, silver veins and silvered traps; it opens Feroxa's lair, which could not be entered before." },
	{ "2026-10-28", "The bookcases of the Edron academy library open again; a bookcase only hands over Milos' notes while you are looking for them." },
	{ "2026-10-28", "Milos' notes now lie in the same bookcases as in Tibia (two on the library's third floor, one on the fourth) and the scribbled note in a box in the corner of Puffels' room." },
	{ "2026-10-28", "More were-creatures on the first floor of the Edron Lycanthropes Cave: its five quieter rooms now hold twice as many or more." },
	{ "2026-10-30", "The shadow bite plant in the Edron Earth Elemental Cave (second floor) is there now, as in Tibia." },
	{ "2026-10-30", "The Grimvale dock (pier and boat) is a protection zone, as in Tibia." },
	{ "2026-10-30", "Dawnport: you can stay until level 50 (was 20) to finish its quests, and skills and magic level are no longer capped there." },
	{ "2026-10-30", "A character can now be deleted with the account editor on the server PC (option 5, server stopped)." },
	{ "2026-10-30", "To Outfox a Fox (Budrik's mining helmet) now shows in the Tibia Tales quest log, also for those who already finished it." },
	{ "2026-11-01", "Dawnport has no level limit any more: you can stay as long as you like and leave when you choose your vocation." },
	{ "2026-11-01", "Budrik's minotaur task (Turmoil of War, then The Horned Fox) can be taken at any level, not only up to level 40." },
	{ "2026-11-01", "The Dorm Key works again: say key to Woblin, then reward. Mr Morris answers every Dawnport task at every step, and kill tasks start with the first kill." },
	{ "2026-11-01", "Dawnport: Inigo buys creature products, gives his hints one by one and no longer sends you to Rookgaard when you say leave or sure." },
	{ "2026-11-01", "Dawnport: Oressa heals when you say heal, Coltrayne sells weapons and armor behind his counter again, and the bankers answer more questions." },
	{ "2026-11-01", "The Explorer Society: Angus and Mortimer answer every step and say what is missing (an ice pick is not the dwarven pickaxe). Black Bert's strange powder counts, and Elvith sells a lost poetry book." },
	{ "2026-11-01", "The Explorer Society: the spectral stone step works (the essence was never given), and Lurik in Svargrond now gives his missions, which open the Liberty Bay - Svargrond portal." },
	{ "2026-11-01", "New achievements: Just in Time (ice delivery or Rashid's cheese) and Explorer (spectral dress)." },
	{ "2026-11-01", "The Explorer Society: the three missions of each of the first three ranks can be taken together, in any order; after the third you are promoted." },
	{ "2026-11-01", "New: The Frozen Trench. Lurik in Svargrond sends you to dive from the ship south of Tyrsung (helmet of the deep) and find a lost explorer; the trench is full of quara now. Achievement Sea Scout." },
	{ "2026-11-01", "Prey and Hunting Tasks cost Prey Wildcards again, as in Tibia (5 to choose from the full list, lock a slot or cancel a task, 1 to reroll a bonus); list rerolls stay free and the third slot stays open. Daily reward days 3 and 5 give 2 Prey Wildcards too." },
	{ "2026-11-01", "Rerolling a Prey or Hunting Task list costs gold again (level x 200), but each slot has one free reroll a day, back at midnight, and the list after claiming a Hunting Task is free. Daily reward days 3 and 5 now give 5 Prey Wildcards each." },
	{ "2026-11-01", "Grimvale Quest, The Curse Spreads: the alchemical apparatus is back on the north counter of Sinclair's laboratory, so the nightshade distillate can be brewed." },
	{ "2026-11-01", "Grimvale Quest: the wooden grinder in the academy now stands in the middle of its room, complete with its four wooden arms, as in Tibia." },
	{ "2026-11-01", "Grimvale Quest, The Curse Spreads: the basin in the Last Sanctum now moves the quest on; the Moonshadow ritual (the V of white tiles under Grimvale) is what opens the Mystic Flame into the Last Sanctum, as in Tibia. The basin looks tainted until someone lifts the curse, Maeryn can start the mission, NPCs use the Tibia lines, the symbol of Suon also works next to a totem, and finishing it together with The Curse of the Full Moon gives Over the Moon." },
	{ "2026-11-01", "Grimvale Quest, The Curse of the Full Moon now follows TibiaWiki BR: four tasks (Nightshades, Silver Traps, Were-Creatures, Moonshadow). Were-creature kills count from the first one, without talking to Maeryn. Feroxa needs the 50 kills and the Moonshadow ritual; defeating her completes the mission, and both have to be done again (ask Maeryn) to face her once more." },
	{ "2026-11-01", "The Order of the Cobra is complete: the quest log starts in the Cobra Bastion, its ten brass-shod chests give a daily reward, lamp oil burns the tendrils, the skeleton gives Key 0303, the chess notes can be read, Gaffir's secret room opens and the chess board unlocks Scarlett's metal wall." },
	{ "2026-11-02", "Cobra Bastion: escort the Cart Packed with Gold up the basement tunnel after the Custodian (break the clutter, oil its wheels, smash it at the end for loot); the fire walls work; toss a coin in the treasure room to lift the curse of the Strange Rats; Scarlett now taunts everyone in the Bastion when her fight starts." },
	{ "2026-11-02", "Grave Danger: the quest log shows the graves correctly (visited ones were shown as still to find), Jack Springer takes your report at any time, King Zelos' sealed door opens after his briefing, holy water works on both halves of a grave, the emptied graves count when you reach them, and only those who really fought the Custodian pass his flames." },
	{ "2026-11-02", "Grimvale Quest: the three dark stone totems at the sources of the ley lines (Krailos, Banuta, Vengoth) now stand on the same squares as in Tibia, and the stone tablet with ley lines tells you when you are at a source." },
	{ "2026-11-02", "Triangle Tower Quest: the lever in the rubble by the river (desert side, east of the tower) now opens and closes the tower entrance every time; before, once closed, the entrance stayed shut until the server restarted." },
	{ "2026-11-02", "Adventurers' Guild: two new magic forcefields beside the exit take you back to the last two places where you used your adventurer's stone (right = the last one, left = the one before); look at the sign above each field to see where it leads you." },
	{ "2026-11-02", "The Ape City Quest: in deeper Banuta the four canopic jars now break with any melee weapon or a crowbar, and once all four are broken the teleport takes everyone for 5 minutes. Hairycles, Brewster, Ustan and Dermot now say exactly what the wikis show, Hairycles has more to talk about and sells bananas from mission 6 on (statue kits after mission 9)." },
	{ "2026-11-02", "The Dorm Key (Dawnport): Old Nasty bites much more often now. Once Woblin has asked you for the fish, each cast with a worm in his pond has a 1 in 4 chance to catch it." },
	{ "2026-11-02", "Sanctuary of the Lizard God (Dawnport): after offering the snake eggs on the altar, the portal really takes you to the sanctuary now (it always sent you back). Only one egg is used, and if you already offered one you can walk right in." },
	{ "2026-11-02", "Blood Brothers Quest: the whole quest now works, from Julius' map of Vengoth to the four vampire brothers in the castle, with A Wandering Soul, A Fading Memory, the diary pages and the blood goblet. Two of you with charged blood crystals on two of the castle spots are enough to get in, and anyone can wake Marziel. Armenius laughs at 'alori mort' like in Tibia, and sometimes shows his true face." },
	{ "2026-11-02", "Grimvale: the six silver veins on the third floor underground are now proper parts of the cave walls, each next to floor you can stand on, so a pick works on them (before they looked broken and could not be mined)." },
	{ "2026-11-02", "In Service of Yalahar: the city guards take their reports in any order, the notes of Palimuth and Azerus can be read, the weapon crystal really helps Azerus, three ghost residues fill the charm, Morik and the ghost charm come back if lost, Tamerin understands 'warbeasts', and choosing a side gives Follower of Palimuth, Follower of Azerus or Turncoat. The treasure room has a fourth chest with the Yalahari Footwraps." },
	{ "2026-11-02", "Accounts: the account editing tool on the server PC can now create a new character on an account (no vocation, on Dawnport), next to renaming, changing sex and deleting." },
	{ "2026-11-02", "Spells are free now: every spell the spell teachers sell is learned by itself as soon as you reach its level (you get a message for each one), and at login you get all the ones you already have the level for. Quest spells (monk shrines) and Wheel of Destiny spells are still earned as before." },
	{ "2026-11-02", "Sap Strength (sorcerers) can now be cast from level 175, as in Tibia (it needed level 275 before)." },
	{ "2026-11-02", "Houses have a monthly rent again, as in Tibia: every 30 days the house's rent is taken from your bank (keep it there!). Buying still costs the price once and covers the first month; houses you already own have 30 free days. Without the money you get a warning every day for 7 days, then the house is taken back and its items go to your depot. House prices and rents are now Tibia's (about 1.5 times the old prices). Say !house to see when each of your houses is paid until." },
}
